// Package inputschema is the input contract of the endpoints this service ports: each zod schema's
// top-level keys and the defaults it applies to an absent key, as the app's own projection of them
// (z.toJSONSchema) answers.
//
// schemas.json is generated by scripts/feed-go-input-schemas.ts, and
// scripts/__tests__/feed-go-input-schemas.schema-drift.test.ts fails when the two differ, so a key
// the app adds to a schema cannot land without the file changing. The parsers accept only the keys
// listed (plus the client transport keys each names), and fall back (`input-unknown-key`) on any
// other: a build that does not know a key never answers as though it were absent. One deliberate
// exception: image.getInfinite also ignores the URL keys zod strips (feed.strippedURLKeys,
// DESIGN.md §5.1).
package inputschema

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"sort"
)

//go:embed schemas.json
var schemasJSON []byte

// The schema names in schemas.json.
const (
	InfiniteImages = "getInfiniteImagesSchema" // image.getImagesAsPostsInfinite, image.getInfinite
	AllModels      = "getAllModelsSchema"      // model.getAll
	ImagesEndpoint = "imagesEndpointSchema"    // GET /api/v1/images
	// POST /api/search/[...path] (siteSearchParamsSchema, siteMultiSearchSchema and its query, and
	// siteFacetSearchSchema).
	SiteSearchParams     = "siteSearchParamsSchema"
	SiteMultiSearch      = "siteMultiSearchSchema"
	SiteMultiSearchQuery = "siteMultiSearchQuerySchema"
	SiteFacetSearch      = "siteFacetSearchSchema"
)

// Schema is one schema's keys and defaults.
type Schema struct {
	name     string
	keys     map[string]bool
	defaults map[string]json.RawMessage
}

var schemas = map[string]*Schema{}

func init() {
	var raw map[string]struct {
		Keys     []string                   `json:"keys"`
		Defaults map[string]json.RawMessage `json:"defaults"`
	}
	if err := json.Unmarshal(schemasJSON, &raw); err != nil {
		panic("inputschema: schemas.json: " + err.Error())
	}
	for _, name := range []string{InfiniteImages, AllModels, ImagesEndpoint, SiteSearchParams, SiteMultiSearch, SiteMultiSearchQuery, SiteFacetSearch} {
		s, ok := raw[name]
		if !ok || len(s.Keys) == 0 {
			panic("inputschema: schemas.json has no keys for " + name)
		}
		keys := make(map[string]bool, len(s.Keys))
		for _, k := range s.Keys {
			keys[k] = true
		}
		schemas[name] = &Schema{name: name, keys: keys, defaults: s.Defaults}
	}
}

// Get returns a schema by name (one of the constants); it panics on any other name.
func Get(name string) *Schema {
	s, ok := schemas[name]
	if !ok {
		panic("inputschema: unknown schema " + name)
	}
	return s
}

// Has reports whether key is one of the schema's keys.
func (s *Schema) Has(key string) bool { return s.keys[key] }

// Keys returns the schema's keys, sorted.
func (s *Schema) Keys() []string {
	out := make([]string, 0, len(s.keys))
	for k := range s.keys {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

// Unknown returns the first key (in sorted order) of keys that is neither one of the schema's nor one
// of extra, and whether there is one.
func (s *Schema) Unknown(keys []string, extra map[string]bool) (string, bool) {
	first, found := "", false
	for _, k := range keys {
		if !s.keys[k] && !extra[k] && (!found || k < first) {
			first, found = k, true
		}
	}
	return first, found
}

// DefaultString is the schema's default for key; it panics when the schema has no string default
// there (a regenerated file that dropped it fails this package's tests and every parser's). The
// parsers call it once, from a package-level var, so the panic is at startup and a request never
// decodes JSON for a default.
func (s *Schema) DefaultString(key string) string {
	var v string
	s.decodeDefault(key, &v)
	return v
}

// DefaultInt is DefaultString for an integer default.
func (s *Schema) DefaultInt(key string) int {
	var v int
	s.decodeDefault(key, &v)
	return v
}

func (s *Schema) decodeDefault(key string, dst any) {
	raw, ok := s.defaults[key]
	if !ok {
		panic(fmt.Sprintf("inputschema: %s has no default for %q", s.name, key))
	}
	if err := json.Unmarshal(raw, dst); err != nil {
		panic(fmt.Sprintf("inputschema: %s default for %q: %v", s.name, key, err))
	}
}
